import React, { useState, useEffect } from 'react';
import { Grid, Paper, Typography } from '@mui/material';
import { getFinancialSummary, getStock, getIncome, getExpenses } from '../services/api';

const HomePage = () => {
  const [summary, setSummary] = useState(null);
  const [recentStock, setRecentStock] = useState([]);
  const [recentFinance, setRecentFinance] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [summ, stock, income, expenses] = await Promise.all([
        getFinancialSummary(),
        getStock({ limit: 5 }),
        getIncome({ limit: 5 }),
        getExpenses({ limit: 5 })
      ]);
      
      setSummary(summ);
      setRecentStock(stock);
      setRecentFinance([...income, ...expenses].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5));
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    }
  };

  return (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <Paper elevation={3} sx={{ p: 3 }}>
          <Typography variant="h5" gutterBottom>Financial Summary</Typography>
          {summary ? (
            <Grid container spacing={3}>
              <Grid item xs={12} md={4}>
                <Typography>Total Income:</Typography>
                <Typography variant="h4" color="success.main">
                  ${summary.totalIncome.toFixed(2)}
                </Typography>
              </Grid>
              <Grid item xs={12} md={4}>
                <Typography>Total Expenses:</Typography>
                <Typography variant="h4" color="error.main">
                  ${summary.totalExpenses.toFixed(2)}
                </Typography>
              </Grid>
              <Grid item xs={12} md={4}>
                <Typography>Net Profit/Loss:</Typography>
                <Typography variant="h4" color={summary.netProfit >= 0 ? 'success.main' : 'error.main'}>
                  ${summary.netProfit.toFixed(2)}
                </Typography>
              </Grid>
            </Grid>
          ) : (
            <Typography>Loading...</Typography>
          )}
        </Paper>
      </Grid>

      <Grid item xs={12} md={6}>
        <Paper elevation={3} sx={{ p: 3, height: '100%' }}>
          <Typography variant="h5" gutterBottom>Recent Stock Transactions</Typography>
          {recentStock.length > 0 ? (
            <table style={{ width: '100%' }}>
              <thead>
                <tr>
                  <th style={{ textAlign: 'left' }}>Item</th>
                  <th style={{ textAlign: 'left' }}>Type</th>
                  <th style={{ textAlign: 'right' }}>Qty</th>
                  <th style={{ textAlign: 'right' }}>Amount</th>
                </tr>
              </thead>
              <tbody>
                {recentStock.map(item => (
                  <tr key={item._id}>
                    <td>{item.itemName}</td>
                    <td>{item.type}</td>
                    <td style={{ textAlign: 'right' }}>{item.quantity}</td>
                    <td style={{ textAlign: 'right' }}>${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <Typography>No recent stock transactions</Typography>
          )}
        </Paper>
      </Grid>

      <Grid item xs={12} md={6}>
        <Paper elevation={3} sx={{ p: 3, height: '100%' }}>
          <Typography variant="h5" gutterBottom>Recent Financial Transactions</Typography>
          {recentFinance.length > 0 ? (
            <table style={{ width: '100%' }}>
              <thead>
                <tr>
                  <th style={{ textAlign: 'left' }}>Type</th>
                  <th style={{ textAlign: 'left' }}>Category</th>
                  <th style={{ textAlign: 'right' }}>Amount</th>
                </tr>
              </thead>
              <tbody>
                {recentFinance.map(item => (
                  <tr key={item._id}>
                    <td>{item.amount ? 'Income' : 'Expense'}</td>
                    <td>{item.category?.name || 'N/A'}</td>
                    <td style={{ textAlign: 'right' }}>${item.amount.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <Typography>No recent financial transactions</Typography>
          )}
        </Paper>
      </Grid>
    </Grid>
  );
};

export default HomePage;
